window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2589e45d269244ae"]={"versions": [{"id": "FIG-2589e45d269244ae", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Datentypen der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection), spezifisch für das Profil 4 (<code>E2E Profile 4</code>). Das Diagramm modelliert die statische Datenstruktur des Empfänger-Zustands (<code>E2E_P04CheckStateType</code>) sowie die zugehörige Enumeration für den Prüfstatus (<code>E2E_P04CheckStatusType</code>) innerhalb des Modulpakets <code>E2E_P04Types</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei typisierte Entitäten mit einer gerichteten Abhängigkeitsbeziehung (gestrichelte Pfeillinie von der Struktur zum Typ):</p>\n<ul class=\"fig-list\">\n<li><strong>«structure» <code>E2E_P04Types::E2E_P04CheckStateType</code></strong>:</li>\n<li><code>+ Counter :uint16</code>: 16-Bit-Sequenzzähler des zuletzt erfolgreich empfangenen bzw. geprüften Datenpakets.</li>\n<li><code>+ Status :E2E_P04CheckStatusType</code>: Aktueller Prüfstatus der Profil-4-Prüffunktion.</li>\n<li><strong>«type» <code>E2E_P04Types::E2E_P04CheckStatusType</code></strong> (Aufzählungstyp/Statuswerte):</li>\n<li><code>+ E2E_P04STATUS_OK = 0x00</code>: Datenpaket intakt und Sequenzzähler korrekt inkrementiert.</li>\n<li><code>+ E2E_P04STATUS_NONEWDATA = 0x01</code>: Keine neuen Daten seit dem letzten Check empfangen.</li>\n<li><code>+ E2E_P04STATUS_ERROR = 0x02</code>: Datenfehler (z. B. CRC- oder Längenfehler) festgestellt.</li>\n<li><code>+ E2E_P04STATUS_REPEATED = 0x08</code>: Identischer Sequenzzähler wiederholt empfangen.</li>\n<li><code>+ E2E_P04STATUS_OKSOMELOST = 0x20</code>: Sequenzzähler inkrementiert, jedoch unter Verlust einzelner Zählschritte im tolerierten Rahmen.</li>\n<li><code>+ E2E_P04STATUS_WRONGSEQUENCE = 0x40</code>: Sequenzzählerabweichung außerhalb des zulässigen Fensters / unzulässiger Sprung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Datenstrukturdiagramm stellt die Abbildung keine dynamischen Sequenzen oder Zustandsübergänge dar. Die Struktur dient als Zustandsspeicher (<code>State</code>) für die Ausführung der Prüffunktion <code>E2E_P04Check</code>. Bei jedem Funktionsaufruf wird die Datenstruktur aktualisiert: Der Zählerstand wird abgeglichen und das Feld <code>Status</code> auf einen der durch <code>E2E_P04CheckStatusType</code> definierten Hexadezimalwerte gesetzt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datentypdefinition für die C-Implementierung der AUTOSAR E2E Library für Profil 4:</p>\n<ul class=\"fig-list\">\n<li><code>E2E_P04CheckStateType</code> bildet die Schnittstelle zur Speicherung des Verifikationszustands auf Empfängerseite ab (<code>uint16</code> für Counter, Aufzählungstyp für Status).</li>\n<li>Die Statuskonstanten besitzen feste numerische Hexadezimalwerte (<code>0x00</code>, <code>0x01</code>, <code>0x02</code>, <code>0x08</code>, <code>0x20</code>, <code>0x40</code>), die als Bitmasken bzw. eindeutige Fehlercodes im Empfängercode und in übergeordneten E2E-Zustandsmaschinen ausgewertet werden.</li>\n</ul>"}, {"id": "FIG-53ca86f05945d6df", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Datentypen der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection), spezifisch für das Profil 4 (<code>E2E Profile 4</code>). Das Diagramm modelliert die statische Datenstruktur des Empfänger-Zustands (<code>E2E_P04CheckStateType</code>) sowie die zugehörige Enumeration für den Prüfstatus (<code>E2E_P04CheckStatusType</code>) innerhalb des voll qualifizierten Paketpfads <code>E2E::E2E_P04Types</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei typisierte Entitäten mit einer gerichteten Abhängigkeitsbeziehung (gestrichelte Pfeillinie von der Struktur zum Typ):</p>\n<ul class=\"fig-list\">\n<li><strong>«structure» <code>E2E::E2E_P04Types::E2E_P04CheckStateType</code></strong>:</li>\n<li><code>+ Counter :uint16</code>: 16-Bit-Sequenzzähler des zuletzt erfolgreich empfangenen bzw. geprüften Datenpakets.</li>\n<li><code>+ Status :E2E_P04CheckStatusType</code>: Aktueller Prüfstatus der Profil-4-Prüffunktion.</li>\n<li><strong>«type» <code>E2E::E2E_P04Types::E2E_P04CheckStatusType</code></strong> (Aufzählungstyp/Statuswerte):</li>\n<li><code>+ E2E_P04STATUS_OK = 0x00</code>: Datenpaket intakt und Sequenzzähler korrekt inkrementiert.</li>\n<li><code>+ E2E_P04STATUS_NONEWDATA = 0x01</code>: Keine neuen Daten seit dem letzten Check empfangen.</li>\n<li><code>+ E2E_P04STATUS_ERROR = 0x02</code>: Datenfehler (z. B. CRC- oder Längenfehler) festgestellt.</li>\n<li><code>+ E2E_P04STATUS_REPEATED = 0x08</code>: Identischer Sequenzzähler wiederholt empfangen.</li>\n<li><code>+ E2E_P04STATUS_OKSOMELOST = 0x20</code>: Sequenzzähler inkrementiert, jedoch unter Verlust einzelner Zählschritte im tolerierten Rahmen.</li>\n<li><code>+ E2E_P04STATUS_WRONGSEQUENCE = 0x40</code>: Sequenzzählerabweichung außerhalb des zulässigen Fensters / unzulässiger Sprung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Datenstrukturdiagramm stellt die Abbildung keine dynamischen Sequenzen oder Zustandsübergänge dar. Die Struktur dient als Zustandsspeicher (<code>State</code>) für die Ausführung der Prüffunktion <code>E2E_P04Check</code>. Bei jedem Funktionsaufruf wird die Datenstruktur aktualisiert: Der Zählerstand wird abgeglichen und das Feld <code>Status</code> auf einen der durch <code>E2E_P04CheckStatusType</code> definierten Hexadezimalwerte gesetzt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datentypdefinition für die C-Implementierung der AUTOSAR E2E Library für Profil 4:</p>\n<ul class=\"fig-list\">\n<li><code>E2E_P04CheckStateType</code> bildet die Schnittstelle zur Speicherung des Verifikationszustands auf Empfängerseite ab (<code>uint16</code> für Counter, Aufzählungstyp für Status).</li>\n<li>Die Statuskonstanten besitzen feste numerische Hexadezimalwerte (<code>0x00</code>, <code>0x01</code>, <code>0x02</code>, <code>0x08</code>, <code>0x20</code>, <code>0x40</code>), die als Bitmasken bzw. eindeutige Fehlercodes im Empfängercode und in übergeordneten E2E-Zustandsmaschinen ausgewertet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-2589e45d269244ae", "to": "FIG-53ca86f05945d6df", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Namespace / Paketpfad</strong>: Voranstellung des übergeordneten AUTOSAR-Pakets <code>E2E::</code> vor den Typbezeichnern (<code>E2E_P04Types::E2E_P04CheckStateType</code> -> <code>E2E::E2E_P04Types::E2E_P04CheckStateType</code> und <code>E2E_P04Types::E2E_P04CheckStatusType</code> -> <code>E2E::E2E_P04Types::E2E_P04CheckStatusType</code>).</li>\n</ul>"}]};
